  CO.balance = (mid, cur) => rd(ops().filter(o => live(o) && o.memberId === mid && o.currency === cur && (o.type === 'deposit' || o.type === 'withdraw')).reduce((s, o) => s + (o.type === 'deposit' ? o.amount : -o.amount), 0), cur);
  CO.savers = () => { const m = {}; ops().filter(o => live(o) && (o.type === 'deposit' || o.type === 'withdraw')).forEach(o => { (m[o.memberId] = m[o.memberId] || {})[o.currency] = 1; }); return Object.entries(m).map(([id, c]) => ({ id, cur: Object.keys(c) })); };
  CO.savingsTotal = () => ops().filter(live).filter(o => o.type === 'deposit' || o.type === 'withdraw').reduce((s, o) => s + main(o, o.type === 'deposit' ? o.amount : -o.amount), 0);

