    const collected = rd(Object.values(paid).reduce((s, v) => s + v, 0), t.currency), fee = rd(collected * (t.feePct || 0) / 100, t.currency), payout = l.find(o => o.type === 'payout') || null, due = CO.due(t.start, t.freq, k);
